head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

scwin.btn_setReadOnlyTrue_onclick = function (e) {
    var objComp = $p.getComponentById("target_accordion");
    objComp.setReadOnly(true);
    scwin.setReturnValue("[setReadOnly(true) 호출] getReadOnly() = " + objComp.getReadOnly());
};

scwin.btn_setReadOnlyFalse_onclick = function (e) {
    var objComp = $p.getComponentById("target_accordion");
    objComp.setReadOnly(false);
    scwin.setReturnValue("[setReadOnly(false) 호출] getReadOnly() = " + objComp.getReadOnly());
};

// target_accordion 이벤트 핸들러 (차단 여부 확인용)
scwin.target_accordion_onclick = function (panel, open) {
    var objComp = $p.getComponentById("target_accordion");
    scwin.setReturnValue("=====target_accordion_onclick===== (readOnly : " + objComp.getReadOnly() + ")");
    scwin.setReturnValue("    panel.id : " + (panel ? panel.id : "null") + " / open : " + open);
};

scwin.target_accordion_onpanelload = function (panelID, userID) {
    scwin.setReturnValue("=====target_accordion_onpanelload===== panelID : " + panelID);
};

scwin.target_accordion_onpanelunload = function (panelID, userID) {
    scwin.setReturnValue("=====target_accordion_onpanelunload===== panelID : " + panelID);
};
